import * as THREE from 'three';
import shader from '@/assets/js/TestModel/shader.js';

var materialCarBody2Tone2 = null;
var material = {

    setMaterial(child) {
        child.material = materialCarBody2Tone2;
    },
    materialSetting() {
        // Add skybox
        var path = '/models/textures/skybox/light/';
        var format = '.png';
        var urlsWindow = [
            path + 'emptyBg' + format, path + 'emptyBg' + format,
            path + 'sky_B_2_2' + format, path + 'emptyBg' + format,
            path + 'emptyBg' + format, path + 'emptyBg' + format,
        ];
        var lightCubeWindow = new THREE.CubeTextureLoader().load(urlsWindow);

        path = '/models/textures/skybox/light/'
        var urlsEnv = [
            path + 'px' + format, path + 'nx' + format,
            path + 'py' + format, path + 'ny' + format,
            path + 'pz' + format, path + 'nz' + format,
        ];
        var envCube = new THREE.CubeTextureLoader().load(urlsEnv);

        var vertexShaderGPM = shader.getVertex();
        var fragmentShaderGPM = shader.getFragment();
        var uniforms2Tone2 = {
            paintColor1: { type: "c", value: new THREE.Color(0xaaaaaa) },
            paintColor2: { type: "c", value: new THREE.Color(0x000000) },
            paintColor3: { type: "c", value: new THREE.Color(0x000000) },
            glossLevel: { type: "f", value: 0.1, min: 0.0, max: 5.0 },
            brightnessFactor: { type: "f", value: 0.8, min: 0.0, max: 1.0 },
            envMap: { type: "t", value: lightCubeWindow },
            envMap2: { type: "t", value: envCube },
            microflakeNMap: { type: "t", value: new THREE.TextureLoader('textures/urx/car/SparkleNoiseMap2.png') },
            flakeColor: { type: "c", value: new THREE.Color(0x777777) },
            flakeScale: { type: "f", value: -30.0, min: -50.0, max: 1.0 },
            fFresnel1ClampMin: { type: "f", value: 0.1, min: 0.0, max: 1.0 },
            fFresnel2ClampMin: { type: "f", value: 0.0, min: 0.0, max: 1.0 },
            normalPerturbation: { type: "f", value: 1.5, min: -1.0, max: 1.0 },
            microflakePerturbationA: { type: "f", value: 0.0, min: -1.0, max: 1.0 },
            microflakePerturbation: { type: "f", value: 0.48, min: 0.0, max: 1.0 },
            paintColorAlpha: { type: "f", value: 1.0, min: 0.0, max: 1.0 },
        };
        uniforms2Tone2.microflakeNMap.value.wrapS = uniforms2Tone2.microflakeNMap.value.wrapT = THREE.RepeatWrapping;
        materialCarBody2Tone2 = new THREE.ShaderMaterial(
            {
                uniforms: uniforms2Tone2,
                vertexShader: vertexShaderGPM,
                fragmentShader: fragmentShaderGPM,
                extensions: {
                    derivatives: true,
                }
            });

        // var materialBasic = new THREE.LineBasicMaterial({
        //     color: 0x777777,
        //     linewidth: 1,
        // });
    }
}
export default material


